services.AddZeroResilience();

// A query is retried without being asked: a query changes nothing, so trying again
// costs a round trip and nothing else.
public sealed record GetRate(string Pair) : IQuery<decimal>;

// A command is not retried unless it says the second handling is safe. The claim is
// specific: the same command handled twice leaves the state one handling would have.
// That needs the command to carry the identity of what it changes.
public sealed record BookPayment(Guid PaymentId, decimal Amount) : ICommand, IIdempotent;

// Only failures another attempt could change are retried -- Unavailable by default.
// Validation and Forbidden never are: the same input fails identically.
services.AddZeroResilience(options =>
{
    options.MaxAttempts = 4;
    options.RetryOn.Add(ErrorKind.Conflict);
});
